const rawText = $input.first().json.text;

let cleaned = rawText.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```(json)?\n/, '').replace(/```$/, '').trim();
}

let recipes;
try {
  recipes = JSON.parse(cleaned);
} catch (error) {
  throw new Error('Failed to parse Gemini response as JSON: ' + error.message);
}

if (!Array.isArray(recipes) || recipes.length !== 3) {
  throw new Error('Expected exactly 3 recipes, got ' + (Array.isArray(recipes) ? recipes.length : typeof recipes));
}

const requestData = $('Validate Recipe Request').first().json;

const enrichedRecipes = recipes.map((recipe) => {
  const servings = requestData.servings;
  const perServing = recipe.nutritionPerServing;

  return {
    ...recipe,
    cuisine: requestData.cuisine,
    servings,
    likes: 0,
    nutritionTotal: {
      energy: perServing.energy * servings,
      protein: perServing.protein * servings,
      carbs: perServing.carbs * servings,
      fat: perServing.fat * servings,
    },
    createdAt: Date.now(),
  };
});

return enrichedRecipes.map((recipe) => ({ json: recipe }));

const recipeItems = $input.all();
const idToken = $('Sign In For Quota Check').first().json.idToken;

return recipeItems.map((item) => ({
  json: {
    idToken,
    recipe: item.json,
  },
}));

const firebaseResponses = $input.all();
const combinedItems = $('Combine Token and Recipe').all();

return firebaseResponses.map((response, index) => ({
  json: {
    id: response.json.name,
    ...combinedItems[index].json.recipe,
  },
}));

const recipes = $('Attach Firebase ID').all().map((item) => item.json);
const quota = $('Prepare Quota Increment').first().json.quota;
const requestId = $('Validate Recipe Request').first().json.requestId;

return [{
  json: {
    requestId,
    patch: {
      status: 'completed',
      recipes,
      quota,
      updatedAt: Date.now(),
    },
  },
}];

const quota = $('Check Quota').first().json;
const newIpCount = quota.ipCount + quota.recipesPerRequest;
const newTotalCount = quota.totalCount + quota.recipesPerRequest;
const remainingRecipes = Math.max(0, Math.min(quota.maxPerIp - newIpCount, quota.maxTotal - newTotalCount));
const canGenerate = remainingRecipes >= quota.recipesPerRequest;
const message = canGenerate
  ? `${remainingRecipes} recipes are available for this browser today.`
  : (newIpCount >= quota.maxPerIp
      ? 'You have reached the daily limit of 9 recipes for this browser. Please try again tomorrow.'
      : 'The daily system-wide limit of 12 recipes has been reached. Please try again tomorrow.');

return [{
  json: {
    ipKey: quota.ipKey,
    date: quota.date,
    idToken: $('Sign In For Quota Check').first().json.idToken,
    quotaBody: JSON.stringify({ count: newIpCount }),
    quota: {
      date: quota.date,
      perIpLimit: quota.maxPerIp,
      systemLimit: quota.maxTotal,
      ipUsed: newIpCount,
      totalUsed: newTotalCount,
      remainingRecipes,
      canGenerate,
      message,
    },
  },
}];

const context = $('Validate Recipe Request').first().json;
const dailyQuota = $input.first().json || {};
const RECIPES_PER_REQUEST = 3;
const MAX_PER_IP = 9;
const MAX_TOTAL = 12;
const ipCount = Number(dailyQuota[context.ipKey]?.count) || 0;
const totalCount = Object.values(dailyQuota).reduce(
  (sum, entry) => sum + (Number(entry?.count) || 0),
  0,
);
const ipExceeded = ipCount + RECIPES_PER_REQUEST > MAX_PER_IP;
const totalExceeded = totalCount + RECIPES_PER_REQUEST > MAX_TOTAL;
const quotaExceeded = ipExceeded || totalExceeded;
const remainingRecipes = Math.max(0, Math.min(MAX_PER_IP - ipCount, MAX_TOTAL - totalCount));
const quotaMessage = quotaExceeded
  ? (ipExceeded
      ? 'You have reached the daily limit of 9 recipes for this browser. Please try again tomorrow.'
      : 'The daily system-wide limit of 12 recipes has been reached. Please try again tomorrow.')
  : `${remainingRecipes} recipes are available for this browser today.`;

return [{ json: {
  ip: context.ip,
  ipKey: context.ipKey,
  date: context.date,
  ipCount,
  totalCount,
  recipesPerRequest: RECIPES_PER_REQUEST,
  maxPerIp: MAX_PER_IP,
  maxTotal: MAX_TOTAL,
  remainingRecipes,
  quotaExceeded,
  quotaStatus: quotaExceeded ? 'exceeded' : 'ok',
  quotaMessage,
} }];

const payload = $input.first().json;
const failure = payload.execution ?? payload.trigger ?? {};
const error = failure.error ?? {};
const cause = error.cause ?? {};

const workflowId = payload.workflow?.id ?? 'unknown';
const workflowName = payload.workflow?.name ?? 'Unknown workflow';
const executionId = payload.execution?.id ?? 'not available';
const executionUrl = payload.execution?.url ?? 'not available';
const mode = failure.mode ?? 'unknown';
const lastNode = payload.execution?.lastNodeExecuted ?? error.node?.name ?? 'trigger';
const errorName = error.name ?? cause.name ?? 'Error';
const message = error.message || cause.message || 'No error message was provided';
const timestamp = new Date().toISOString();

const logEntry = {
  event: 'n8n_workflow_error',
  timestamp,
  workflowId,
  workflowName,
  executionId,
  executionUrl,
  mode,
  lastNode,
  errorName,
  message,
};

// CODE_ENABLE_STDOUT=true forwards this structured entry to the n8n process log.
console.log(JSON.stringify(logEntry));

const text = [
  'An n8n workflow execution failed.',
  '',
  `Workflow: ${workflowName} (${workflowId})`,
  `Execution: ${executionId}`,
  `Mode: ${mode}`,
  `Failed node: ${lastNode}`,
  `Error: ${errorName}: ${message}`,
  `Time (UTC): ${timestamp}`,
  `Execution URL: ${executionUrl}`,
].join('\n');

return [{
  json: {
    ...logEntry,
    subject: `[n8n] ${workflowName} failed at ${lastNode}`,
    text,
  },
}];

const requests = $input.first().json || {};
const entries = Object.entries(requests);

if (entries.length === 0) {
  return [];
}

entries.sort(([, first], [, second]) =>
  (Number(first?.createdAt) || 0) - (Number(second?.createdAt) || 0),
);

const [requestId, record] = entries[0];
const ownerId = String(record.ownerId || '');
let hash = 2166136261;
const groups = ['fd00'];

for (let groupIndex = 0; groupIndex < 7; groupIndex += 1) {
  let value = 0;

  for (const character of ownerId) {
    hash ^= character.charCodeAt(0) + groupIndex;
    hash = Math.imul(hash, 16777619) >>> 0;
    value = (value + hash) >>> 0;
  }

  groups.push((value & 0xffff).toString(16));
}

return [{
  json: {
    requestId,
    ownerId,
    quotaIp: groups.join(':'),
    payload: record.payload || {},
  },
}];

const request = $('Validate Recipe Request').first().json;

return [{
  json: {
    requestId: request.requestId,
    patch: {
      status: 'failed',
      errorMessage: 'Invalid request',
      errorDetails: request.validationErrors,
      updatedAt: Date.now(),
    },
  },
}];

const quota = {
  date: $json.date,
  perIpLimit: $json.maxPerIp,
  systemLimit: $json.maxTotal,
  ipUsed: $json.ipCount,
  totalUsed: $json.totalCount,
  remainingRecipes: $json.remainingRecipes,
  canGenerate: false,
  message: $json.quotaMessage,
};

return [{
  json: {
    requestId: $('Validate Recipe Request').first().json.requestId,
    patch: {
      status: 'failed',
      errorMessage: $json.quotaMessage,
      quota,
      updatedAt: Date.now(),
    },
  },
}];
